"""Destination `sas_restructure_move`: custom steps generated by package-factory; review before approving.

Plan (approved by @claude-demo):
  1. compute_target_keys [custom] Work out target key per file by the 7 rules (exactly one must match, else error/)
  2. custom_delivery [custom_delivery] Move files server-side, verify, delete source, replace tags, report per file

Each custom function: def <step_id>(layout, params, ctx): — only function bodies may be edited
The custom_delivery function: def <step_id>(transfers, params, ctx, aws) -> results
(then `pkf test destination sas_restructure_move` and approve again).
Plan digest: 8293174d60ecbba2757f20822deeccb3ca89c47139580972bdfc12e17293bf61
"""
from __future__ import annotations


def compute_target_keys(layout, params, ctx):
    keys = layout.setdefault("keys", {})
    vs = layout.setdefault("vars", {})
    for path in sorted(layout.get("files", [])):
        if keys.get(path) is not None:
            continue
        parts = path.split("/")
        folders = parts[:-1]
        filename = parts[-1]
        if len(folders) == 0:
            keys[path] = "error/" + path
            vs["rule:" + path] = "error: file at root, no study folder"
            continue
        study = parts[0]
        last = folders[-1]
        fp = "/" + "/".join(folders) + "/"

        if "/adam/" in fp:
            fmt = "adam"
        elif "/sdtm/" in fp:
            fmt = "sdtm"
        elif "raw/" in fp:
            fmt = "raw"
        else:
            fmt = None
        if "_adam_" in fp:
            afmt = "adam"
        elif "_sdtm_" in fp:
            afmt = "sdtm"
        elif "_raw_" in fp or "_restricted_raw_" in fp:
            afmt = "raw"
        else:
            afmt = None

        results = {}
        # R1 CDAP
        if "/data_reuse/" in fp and "/cdap_" in fp and fmt:
            if "/cdap_csr" in fp:
                results["CDAP"] = "/".join([study, "extended_primary_use", "primary", fmt, filename])
            elif "_ia" in last:
                pieces = last.split("_")
                if len(pieces) < 3 or not pieces[2].startswith("ia"):
                    results["CDAP"] = "error"
                else:
                    results["CDAP"] = "/".join([study, "extended_primary_use", "interim", fmt, "ia_" + pieces[2][2:], filename])
            else:
                pieces = last.split("_")
                if len(pieces) < 2:
                    results["CDAP"] = "error"
                else:
                    results["CDAP"] = "/".join([study, "extended_primary_use", "other", fmt, pieces[1], filename])
        # R2 IDAP
        if "/data_reuse/" in fp and "/idap" in fp and fmt:
            results["IDAP"] = "/".join([study, "internal_reuse", fmt, last, filename])
        # R3 MED
        if "/data_reuse/" in fp and "/med" in fp and fmt:
            results["MED"] = "/".join([study, "external_reuse", fmt, last, filename])
        # R4 ANON
        if "_anon_" in fp and afmt:
            if "_anon_csr" in fp:
                results["ANON"] = "/".join([study, "anonymised", "primary", afmt, filename])
            else:
                v = last.split("_")[-1]
                if v.startswith("ia"):
                    results["ANON"] = "/".join([study, "anonymised", "interim", afmt, "ia_" + v[2:], filename])
                else:
                    results["ANON"] = "/".join([study, "anonymised", "other", afmt, v, filename])
        # R5 CDAR
        if "/cdar/" in fp and fmt:
            idx = None
            for i in range(1, len(folders)):
                if folders[i].lower() == "ar":
                    idx = i
                    break
            if idx is None or idx + 1 >= len(folders):
                results["CDAR"] = "error"
            else:
                level = folders[idx + 1].lower()
                if level in ("adam", "sdtm", "raw"):
                    results["CDAR"] = "error"
                elif level == "csr":
                    results["CDAR"] = "/".join([study, "primary", "complete", fmt, filename])
                elif level.startswith("ia"):
                    r = level[2:].lstrip("_")
                    results["CDAR"] = "/".join([study, "primary", "interim", fmt, "ia_" + r, filename])
                else:
                    results["CDAR"] = "/".join([study, "primary", "other", fmt, level, filename])
        # R6 OTHERS
        if "/data_reuse/" in fp and fmt and not any(t in fp for t in ("/med", "/cdap", "/idap", "/anon", "_anon_")):
            results["OTHERS"] = "/".join([study, "other", fmt, last, filename])
        # R7 DEFAULT
        if not any(t in fp for t in ("/data_reuse/", "_anon_", "/cdar/")):
            results["DEFAULT"] = path

        if len(results) == 1:
            name = list(results.keys())[0]
            val = results[name]
            if val == "error":
                keys[path] = "error/" + path
                vs["rule:" + path] = "error: rule " + name + " matched but target cannot be worked out"
            else:
                keys[path] = val
                vs["rule:" + path] = name
        elif len(results) == 0:
            keys[path] = "error/" + path
            vs["rule:" + path] = "error: no rule matched"
        else:
            keys[path] = "error/" + path
            vs["rule:" + path] = "error: multiple rules matched (" + ",".join(sorted(results.keys())) + ")"
    return layout


def custom_delivery(transfers, params, ctx, aws):
    results = []
    delivery = (ctx or {}).get("delivery") or {}
    for t in transfers:
        path = t["path"]
        target_key = t["target_key"]
        is_error = target_key.startswith("error/")
        base_detail = "error/ prefix" if is_error else ""
        extra = {}
        if t.get("etag") is not None:
            extra["CopySourceIfMatch"] = t["etag"]
        if delivery.get("server_side_encryption"):
            extra["ServerSideEncryption"] = delivery["server_side_encryption"]
        if delivery.get("kms_key_id"):
            extra["SSEKMSKeyId"] = delivery["kms_key_id"]
        try:
            aws.s3_destination.copy(
                {"Bucket": t["source_bucket"], "Key": t["source_key"]},
                t["target_bucket"], target_key,
                ExtraArgs=extra, SourceClient=aws.s3_source)
        except Exception as e:
            aws.log.error("copy failed: %s -> %s: %s", t["source_key"], target_key, e)
            results.append({"path": path, "key": target_key, "status": "failed",
                            "detail": "copy failed: %s" % e})
            continue
        try:
            head = aws.s3_destination.head_object(Bucket=t["target_bucket"], Key=target_key)
            if head.get("ContentLength") != t["size"]:
                results.append({"path": path, "key": target_key, "status": "failed",
                                "detail": "target size differs from source size"})
                continue
        except Exception as e:
            results.append({"path": path, "key": target_key, "status": "failed",
                            "detail": "target check failed: %s" % e})
            continue
        try:
            aws.s3_source.delete_object(Bucket=t["source_bucket"], Key=t["source_key"])
        except Exception as e:
            results.append({"path": path, "key": target_key, "status": "failed",
                            "detail": "source delete failed: %s" % e})
            continue
        detail = base_detail
        if not is_error:
            try:
                aws.s3_destination.put_object_tagging(
                    Bucket=t["target_bucket"], Key=target_key,
                    Tagging={"TagSet": [{"Key": "ADDITIONAL_TAG", "Value": path}]})
            except Exception as e:
                aws.log.warning("tagging failed for %s: %s", target_key, e)
                detail = (detail + "; " if detail else "") + "warning: tagging failed: %s" % e
        aws.log.info("moved %s -> %s (%s)", t["source_key"], target_key, detail or "ok")
        results.append({"path": path, "key": target_key,
                        "status": "moved_to_error" if is_error else "moved",
                        "detail": detail})
    return results


CUSTOM = {"compute_target_keys": compute_target_keys, "custom_delivery": custom_delivery}
